import numpy as np
import pandas as pd
import math
import matplotlib.pyplot as plt
import seaborn as sns

import tensorflow as tf
print(tf. __version__)

from tensorflow import keras
from tensorflow.keras import layers
from tensorflow.keras.losses import MeanSquaredError
from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import SimpleRNN, Dense, Embedding,Masking,LSTM, GRU, Conv1D, Dropout
from tensorflow.keras.optimizers import Adam
from tensorflow.keras.preprocessing.sequence import TimeseriesGenerator
from sklearn.preprocessing import MinMaxScaler

from keras.preprocessing import sequence
from keras.models import Sequential
from keras.layers import Dense, Dropout, Embedding, SimpleRNN
from tensorflow.keras.datasets import reuters
from keras.utils import pad_sequences


sns.set_context('notebook')
sns.set_style('white')
np.random.seed(2024)

num_words = 20000
maxlen = 1000
test_split = 0.2
batch_size = 32

(xtrain,ytrain),(xtest,ytest) = reuters.load_data(num_words=num_words,test_split=test_split)

print(ytrain[1:10])

# Set the amount of words per sequence
xtrain = sequence.pad_sequences(xtrain, maxlen=maxlen)
xtest = sequence.pad_sequences(xtest, maxlen=maxlen)

# One data entry has 1000 "words" per sequence.
print(xtest[1])

# Shape of the dataset for xtrain and xtest
print(xtrain.shape, 'Train Shape')
print(xtest.shape, 'Test Shape')

# Set classification to binary categories
ytrain = tf.keras.utils.to_categorical(ytrain,46)
ytest = tf.keras.utils.to_categorical(ytest,46)

lstm_model = Sequential()
lstm_model.add(Embedding(input_dim=num_words, output_dim=300, input_length=maxlen))
lstm_model.add(LSTM(50, input_shape=(num_words, maxlen)))

lstm_model.add(Dense(46))

lstm_model.compile(optimizer='adam', loss='mse')
lstm_model.fit(xtrain,ytrain,batch_size=256,epochs=10,validation_data=(xtest,ytest))
lstm_model.evaluate(xtest, ytest, batch_size=256)